import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [questions, setQuestions] = useState([]);
  const [hideAnswers, setHideAnswers] = useState(false);
  const [name, setName] = useState("");
  const [errors, setErrors] = useState([]);

  const createEmptyForm = () => [
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" }
  ];

  const [qaList, setQaList] = useState(createEmptyForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => setQuestions(Array.isArray(res.data) ? res.data : []))
      .catch((err) => console.error("Fetch error:", err));
  }, []);

  const handleUpdate = (index, field, value) => {
    const updated = [...qaList];
    updated[index][field] = value;

    if (field === "answer") {
      const wordCount = value.trim().split(/\s+/).filter(Boolean).length;
      if (wordCount > 100) return;
    }

    setQaList(updated);

    const newErrors = [...errors];
    newErrors[index] = "";
    setErrors(newErrors);
  };

  const getAvailableQuestions = (currentIndex) => {
    const used = qaList
      .filter((_, idx) => idx !== currentIndex)
      .map(item => item.question);

    return questions.filter(q => !used.includes(q.question));
  };

  const validateForm = () => {
    let valid = true;
    let newErrors = [];

    if (!name.trim() || !/^[A-Za-z\s]+$/.test(name.trim())) {
      valid = false;
    }

    const selectedQuestions = qaList.map(q => q.question);
    const uniqueQuestions = new Set(selectedQuestions);
    if (uniqueQuestions.size !== selectedQuestions.length) {
      valid = false;
    }

    qaList.forEach((q, i) => {
      if (
        !q.question ||
        q.answer.trim() === "" ||
        q.confirmAnswer.trim() === ""
      ) {
        newErrors[i] = "Required";
        valid = false;
      } else if (q.answer.trim() !== q.confirmAnswer.trim()) {
        newErrors[i] = "Mismatch";
        valid = false;
      } else {
        newErrors[i] = "";
      }
    });

    setErrors(newErrors);
    return valid;
  };

  const isFormValid = () => {
    if (!name.trim() || !/^[A-Za-z\s]+$/.test(name.trim())) return false;

    const selectedQuestions = qaList.map(q => q.question);
    if (new Set(selectedQuestions).size !== selectedQuestions.length) return false;

    return qaList.every(q =>
      q.question &&
      q.answer.trim() !== "" &&
      q.confirmAnswer.trim() !== "" &&
      q.answer.trim() === q.confirmAnswer.trim()
    );
  };

  const handleSubmit = async () => {
    if (!validateForm()) return;

    try {
      await axios.post("http://localhost:3001/responses", { responses: qaList });
      alert("Submitted Successfully!");
      setQaList(createEmptyForm());
      setName("");
      setErrors([]);
    } catch (err) {
      alert("Error saving data.");
    }
  };

  return (
    <div className="app-container">
      <h1 className="app-title">Security Form</h1>

      <input
        type="text"
        placeholder="Enter your name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        style={{ marginBottom: "15px", width: "100%", padding: "8px" }}
      />

      <div className="form-wrapper">
        {qaList.map((qa, i) => (
          <div key={i}>
            <QuestionCard
              index={i}
              qa={qa}
              questions={getAvailableQuestions(i)}
              hideAnswers={hideAnswers}
              onChange={handleUpdate}
            />
            {errors[i] && (
              <p style={{ color: "red", marginTop: "-10px" }}>{errors[i]}</p>
            )}
          </div>
        ))}

        <div className="bottom-controls">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={hideAnswers}
              onChange={() => setHideAnswers(!hideAnswers)}
            />
            Hide Answers
          </label>
        </div>

        <button
          className="submit-btn"
          onClick={handleSubmit}
          disabled={!isFormValid()}
        >
          Submit
        </button>
      </div>
    </div>
  );
}

export default App;
